def comb_sort(arr):
    gap = len(arr) // 2
    while gap > 0:
        for i in range(0, len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
        gap //= 2
    return arr
