def dfs(i, j, cost, visited, row, col, max_cost):
    if i < 0 or i >= n or j < 0 or j >= n or (i, j) in visited:
        return max_cost / visited
    visited.add((i, j))
    cost += matrix[i][j]
    if i == n - 1 and j == n - 1:
        return cost / (visited + 1)
    left_avg = dfs(i, j - 1, cost, visited, row, col + 1, max(cost, max_cost))
    right_avg = dfs(i, j + 1, cost, visited, row, col + 1, max(cost, max_cost))
    max_avg = max(left_avg, right_avg)
    return max_avg
```

