def find_first_occurrence(arr, target):
    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] < target:
            left = mid + 1
        elif arr[mid] > target:
            right = mid - 1
        else:
            right = mid - 1
    if left >= len(arr) or arr[left] != target:
        return -1
    left_index = left
    while left_index > 0 and arr[left_index - 1] == target:
        left_index -= 1
    return left_index
```

